        STATUS OFF
        METADATA
            "gml_featureid" "ne_id"
            "gml_include_items" "all"
            "gml_types" "auto"
        END
        FILTER ([pop_max] &gt; 1000000) # only return places with a population &gt; 1 million
        CONNECTIONTYPE OGR
        CONNECTION "data/naturalearth"
        DATA "ne_50m_populated_places_simple"
        CLASS
            STYLE
                COLOR 60 179 113
                OUTLINECOLOR 255 255 255
                OUTLINEWIDTH 0.1
            END
        END
    END
END
